#include <esp_heap_caps.h>

// AI: below section was generated by an AI
// Defaults match the existing ESP-WROVER-KIT panel wiring. Override at build time
// rather than treating the five bus configuration slots as physical GPIOs.
#ifndef WLED_LEDTILE_PINS
#define WLED_LEDTILE_PINS 26, 18, 19, 21, 22, 23, 25
#endif
#ifndef WLED_LEDTILE_CLOCK_HZ
#define WLED_LEDTILE_CLOCK_HZ 2000000
#endif
#ifndef WLED_LEDTILE_DMA_RESERVE
#define WLED_LEDTILE_DMA_RESERVE (32 * 1024)
#endif

static_assert(WLED_LEDTILE_CLOCK_HZ >= 100000 && WLED_LEDTILE_CLOCK_HZ <= 8000000,
              "LedTile clock must be between 100 kHz and 8 MHz");

bool BusLedTile::_claimed = false;

static_assert(Bus::validLedTileProfile(64, 16, 4, 16, 2, 1024, 0, 0), "default LedTile profile must be valid");
static_assert(!Bus::validLedTileProfile(64, 16, 4, 16, 16, 1024, 0, 0), "floor must be shorter than base");
static_assert(!Bus::validLedTileProfile(64, 16, 9, 16, 2, 1024, 0, 0), "depth must not exceed eight bits");
static_assert(!Bus::validLedTileProfile(64, 16, 4, 272, 2, 1024, 0, 0), "validate before narrowing bytes");
static_assert(!Bus::validLedTileProfile(64, 16, 4, 16, 2, 1023, 0, 0), "tile length is fixed");
static_assert(!Bus::validLedTileProfile(64, 16, 4, 16, 2, 1024, -1, 0), "negative starts are invalid");
static_assert(!Bus::validLedTileProfile(64, 16, 4, 16, 2, 1024, 0, 1), "skipped pixels are unsupported");

// Convert the persisted panel profile into the standalone driver's configuration.
LedTileConfig BusLedTile::panelConfig(const BusConfig &bc) {
  constexpr int8_t pins[] = {WLED_LEDTILE_PINS};
  static_assert(sizeof(pins) == LedTile::kPinCount, "WLED_LEDTILE_PINS needs seven GPIOs");
  LedTileConfig cfg;
  cfg.pinD1 = pins[0]; cfg.pinD2 = pins[1]; cfg.pinLat = pins[2];
  cfg.pinOe = pins[3]; cfg.pinA0 = pins[4]; cfg.pinA1 = pins[5]; cfg.pinClk = pins[6];
  cfg.bcmBits = bc.pins[2];
  cfg.baseCycles = bc.pins[3];
  cfg.floorCycles = bc.pins[4];
  cfg.clockHz = WLED_LEDTILE_CLOCK_HZ;
  cfg.i2sPort = 1;
  return cfg;
}

// Validate fixed geometry and timing before any DMA allocation or GPIO operation.
bool BusLedTile::validConfig(const BusConfig &bc) {
  return Bus::validLedTileProfile(bc.pins[0], bc.pins[1], bc.pins[2], bc.pins[3], bc.pins[4], bc.count, bc.start, bc.skipAmount);
}

// Include the driver's embedded framebuffer and descriptor chain in WLED's budget.
size_t BusLedTile::memUsage(const BusConfig &bc) {
  return sizeof(BusLedTile) + LedTile::dmaBytesForConfig(panelConfig(bc));
}

// Reserve the singleton and all physical pins, then start a blank DMA waveform.
BusLedTile::BusLedTile(const BusConfig &bc)
: Bus(bc.type, bc.start, bc.autoWhite, bc.count, bc.reversed, true) {
  _hasRgb = true;
  _hasWhite = _hasCCT = false;
  memcpy(_config, bc.pins, sizeof(_config));
  if (!validConfig(bc) || _claimed) {
    DEBUG_PRINTLN(F("LedTile: invalid configuration or another panel already active"));
    errorFlag = ERR_NOT_IMPL;
    return;
  }
  const LedTileConfig cfg = panelConfig(bc);
  const size_t required = LedTile::dmaBytesForConfig(cfg);
  DEBUG_PRINTF("LedTile: DMA free %u, largest block %u, required %u + reserve %u\n",
               unsigned(heap_caps_get_free_size(MALLOC_CAP_DMA)), unsigned(heap_caps_get_largest_free_block(MALLOC_CAP_DMA)),
               unsigned(required), unsigned(WLED_LEDTILE_DMA_RESERVE));
  if (heap_caps_get_free_size(MALLOC_CAP_DMA) < required + WLED_LEDTILE_DMA_RESERVE
      || heap_caps_get_largest_free_block(MALLOC_CAP_DMA) < LedTile::waveformBytesForConfig(cfg) / 4) {
    DEBUG_PRINTLN(F("LedTile: insufficient internal DMA heap; select a lower BCM profile"));
    errorFlag = ERR_NORAM;
    return;
  }
  const int8_t pins[] = {cfg.pinD1, cfg.pinD2, cfg.pinLat, cfg.pinOe, cfg.pinA0, cfg.pinA1, cfg.pinClk};
  if (!PinManager::allocateMultiplePins(pins, LedTile::kPinCount, PinOwner::LedTile, true)) {
    DEBUG_PRINTLN(F("LedTile: physical GPIO conflict"));
    errorFlag = ERR_NOT_IMPL;
    return;
  }
  memcpy(_pins, pins, sizeof(_pins));
  _pinsAllocated = true;
  _claimed = true;
  // WLED has already applied colour gamma; leave only brightness/quantisation here.
  _tile.setGamma(false);
  if (!_tile.begin(cfg)) {
    DEBUG_PRINTF("LedTile: %s\n", _tile.lastError());
    errorFlag = ERR_NORAM;
    _tile.end();
    PinManager::deallocateMultiplePins(_pins, LedTile::kPinCount, PinOwner::LedTile);
    _pinsAllocated = false;
    _claimed = false;
    return;
  }
  _valid = true;
  DEBUG_PRINTF("LedTile: %u waveform bytes, %u Hz refresh\n", unsigned(_tile.waveformBytes()), unsigned(_tile.refreshHz()));
}

// Stop and blank before giving pins and singleton ownership back to WLED.
BusLedTile::~BusLedTile() {
  _tile.end();
  _valid = false;
  if (_pinsAllocated) {
    PinManager::deallocateMultiplePins(_pins, LedTile::kPinCount, PinOwner::LedTile);
    _claimed = false;
  }
}

// Map WLED's local row-major index, optionally rotating the entire tile by 180°.
void BusLedTile::setPixelColor(unsigned pix, uint32_t c) {
  if (!_valid || pix >= _len) return;
  if (_reversed) pix = _len - 1 - pix;
  _tile.setPixel(pix % LedTile::kWidth, pix / LedTile::kWidth, c);
}

uint32_t BusLedTile::getPixelColor(unsigned pix) const {
  if (!_valid || pix >= _len) return 0;
  if (_reversed) pix = _len - 1 - pix;
  return _tile.getPixel(pix % LedTile::kWidth, pix / LedTile::kWidth);
}

void BusLedTile::setBrightness(uint8_t b) {
  _bri = b;
  if (_valid) _tile.setBrightness(b);
}

void BusLedTile::show() {
  if (_valid) _tile.show(); // continuous scanout never blocks waiting for DMA EOF
}

// Report configuration, not seven GPIOs: callers provide OUTPUT_MAX_PINS slots.
size_t BusLedTile::getPins(uint8_t *out) const {
  if (out) memcpy(out, _config, sizeof(_config));
  return OUTPUT_MAX_PINS;
}

std::vector<LEDType> BusLedTile::getLEDTypes() {
  return {{TYPE_LEDTILE, "T", PSTR("LED Tile v2 (64x16)")}};
}
